// Pending-accrual workspace (#726): owed accruals queue as pending rows gating arrears exposure; finalization attaches them (invoice_id, status=invoiced) so they cannot bill twice. NOT the statement itemization — that is invoices.line_items.
type OpenrailsInvoiceItem struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
	InvoiceID  *uuid.UUID
	SourceType string
	SourceID   string
	InvoiceAt  time.Time
	Amount     int64
	Status     string
	Metadata   []byte
	CreatedAt  time.Time
	UpdatedAt  time.Time
}

// Payment attempts and settled payments allocated to a specific invoice.
type OpenrailsInvoicePayment struct {
	ID               uuid.UUID
	MerchantID       uuid.UUID
	CustomerID       uuid.UUID
	InvoiceID        uuid.UUID
	LedgerTransferID *uuid.UUID
	Currency         string
	Amount           int64
	Status           string
	Rail             *string
	RailPaymentID    *string
	FailureCode      *string
	FailureMessage   *string
	AttemptedAt      time.Time
	SettledAt        *time.Time
	CreatedAt        time.Time
	UpdatedAt        time.Time
	// PSP that took this invoice payment attempt. Required on every real rail (invoice_payments_psp_required_on_rail); NULL only for off-rail manual settlement — or#893.
	PspID           *uuid.UUID
	FailureReason   *string
	PaymentMethodID *uuid.UUID
	IdempotencyKey  *string
}

// Per-invoker spend limits (#473/#517): the payer caps how much a delegated invoker/role can spend of the payer's money. {scope, scope_key, windows[]} composed in one admit verdict over the payer balance. Payer-set only.
type OpenrailsInvokerSpendLimit struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Scope      string
	// Immutable scope discriminator: role uuid (scope=role), invoker string (scope=invoker), or tier key (scope=invoker_tier).
	ScopeKey  string
	Windows   []byte
	CreatedAt time.Time
	UpdatedAt time.Time
}

// #512 double-entry ledger accounts. One account belongs to exactly one (merchant, currency) ledger; TB-style posted/pending counters are maintained from immutable ledger_transfers and verified by reconciliation. account_type identifies its role (customer_balance, platform_revenue, processor_clearing, arrears_liability, expired_credits, fx_liquidity, world).
type OpenrailsLedgerAccount struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	// NULL for system accounts (one per merchant+currency); set for per-customer balance accounts.
	CustomerID *uuid.UUID
	// Account role within a (merchant, currency) ledger. arrears_liability is PER-CUSTOMER (or#897): its negated balance is that payer's outstanding owed, read O(1) on the admission path. customer_balance is per-customer; processor_clearing / platform_revenue / expired_credits / revoked_credits / fx_liquidity / world are merchant-wide system accounts.
	AccountType string
	Currency    string
	// TB sign flag: balance (credits-debits) may not go below zero (minus an applier-supplied arrears floor). Set on customer_balance.
	DebitsMustNotExceedCredits bool
	CreditsMustNotExceedDebits bool
	// Phase H maintained counter: posted credits for O(1) balance reads.
	CreditsPosted int64
	// Phase H maintained counter: posted debits for O(1) balance reads.
	DebitsPosted int64
	CreatedAt    time.Time
}

// #512 immutable double-entry transfers. Append-only (role granted SELECT,INSERT only). A transfer moves amount debit->credit within ONE (merchant, currency) ledger; capture/void/refund/expiry are NEW rows, never updates. ledger_accounts counters are a maintained projection of this table.
type OpenrailsLedgerTransfer struct {
	ID              uuid.UUID
	MerchantID      uuid.UUID
	DebitAccountID  uuid.UUID
	CreditAccountID uuid.UUID
	Amount          int64
	Currency        string
	TransferType    string
	// Debit-account floor used by the counter trigger for debits_must_not_exceed_credits accounts. Usually 0; arrears paths pass the current credit-line allowance.
	AllowDebitNegativeUpTo int64
	// Opaque origin key (e.g. 'grant'/grant_id, 'payment'/transaction_id). Ledger purity: business joins live in control-plane tables.
	Source   string
	SourceID string
	// Credit-lot attribution. grant_id/invoice_id/customer_id deliberately carry NO FKs (ledger purity, #709): the append-only ledger never blocks or cascades on control-plane rows.
	GrantID    *uuid.UUID
	CustomerID *uuid.UUID
	InvokerID  *string
	Resource   *string
	InvoiceID  *uuid.UUID
	CreatedAt  time.Time
	// or#894 engine-composed money-operation kind (capture / spend / withdraw / usage:<event_type> / deposit / ...). Part of the idempotency coordinate together with (source, source_id): two different operations sharing a caller key must not alias.
	Operation string
}

// Merchant / billing-namespace directory: a dumb billing bucket (whose books a row goes on). GLOBAL (control-plane) table, not tenant-scoped. Carries ONLY billing/money-rail state, NO auth. Merchants are registered explicitly; there is no default merchant. RLS-exempt by design: it IS the tenant directory — the scope, not a scoped row.
type OpenrailsMerchant struct {
	ID uuid.UUID
	// Stable merchant slug used in merchant-scoped routes and resolution.
	Slug   string
	Status string
	// The merchant's own AuthKit permission-group id (#567): a merchant is a top-level `merchant` group, child of `root`. Bare `text`, NO FK into the auth schema (#544 portability guard). NULL in embedded (no control plane). Used to resolve a merchant from its authenticated group id.
	PermissionGroupID *string
	CreatedAt         time.Time
	UpdatedAt         time.Time
	DeletedAt         *time.Time
	// human-readable merchant name for end-user display / invoices; NULL = fall back to slug.
	DisplayName *string
	// Canonical Host-header value this merchant resolves from (#734), e.g. "api.acme.example". NULL = no Host resolution for this merchant. Lowercase, no scheme/port.
	ApiHost *string
}

// One merchant-scoped JSON configuration row. Missing keys use service defaults.
type OpenrailsMerchantConfiguration struct {
	MerchantID uuid.UUID
	// JSONB merchant config. delegated_invoker_wasted_spend_windows is an array of {key, window_seconds, limit}; amount values use the request currency internal precision.
	Config    []byte
	CreatedAt time.Time
	UpdatedAt time.Time
}

// Wrapped per-merchant Data Encryption Keys for envelope encryption-at-rest (issue #227). wrapped_dek = merchant DEK sealed with the master key (AES-256-GCM, nonce||ct||tag). Master key lives in config/env (self-hosted) or KMS (production), never in the DB. Merchant-owned and RLS protected.
type OpenrailsMerchantDek struct {
	MerchantID uuid.UUID
	// AES-256-GCM(master_key, merchant_dek): nonce(12) || ciphertext(32) || tag(16).
	WrappedDek []byte
	CreatedAt  time.Time
	UpdatedAt  time.Time
}

// #836/#835 per-merchant destructive-action policy: destructive_actions_enabled is the per-merchant emergency stop (the instance switch in destructive_action_switch gates it globally); enforce_armed_at is the first-enforce gate — NULL means the merchant's provider pull runs advisory (findings only, zero mutations) until an operator reviews the first pull and arms it.
type OpenrailsMerchantDestructivePolicy struct {
	ID                        uuid.UUID
	MerchantID                uuid.UUID
	DestructiveActionsEnabled bool
	// #835: NULL = advisory-only pulls for this merchant. Absence of a row is the same as NULL, so a newly onboarded merchant is surveyed before it is enforced.
	EnforceArmedAt       *time.Time
	FirstPullCompletedAt *time.Time
	UpdatedBy            *string
	Reason               *string
	UpdatedAt            time.Time
}

// #736 MERCHANT-operator-facing in_app alert store (console bell). rule_id references the source alert_rules row informationally (no FK: notifications outlive rule deletion).
type OpenrailsMerchantNotification struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	Severity   string
	Title      string
	Body       string
	Link       string
	RuleID     *uuid.UUID
	Data       []byte
	CreatedAt  time.Time
	ReadAt     *time.Time
}

// or#858: the manifest of what a merchant purge is ABOUT TO DESTROY — per-table row counts, merchant secret NAMES, and the explicit list of what is not captured. It is NOT a backup and restores nothing; the only restore path is Postgres PITR (docs/backup-and-recovery.md). Merchant deletion is gated on a matching inventory so the operator has seen the blast radius, not so the data can come back. Was merchant_exports (#225), a name that promised a restore point that never existed.
type OpenrailsMerchantPurgeInventory struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	Status     string
	// The inventory manifest: row_counts, total_rows, secret_names (never values), not_captured, is_backup=false. total_rows must still match at purge time — a stale inventory does not authorise a purge.
	Manifest    []byte
	CreatedAt   time.Time
	CompletedAt *time.Time
}

// DB-backed per-merchant secret store (issue #225). Namespaced by (merchant_id, name). The Vault-backed store keeps the same addressing but holds values in Vault. Merchant-owned and RLS protected.
type OpenrailsMerchantSecret struct {
	MerchantID uuid.UUID
	Name       string
	Value      string
	Version    int32
	CreatedAt  time.Time
	UpdatedAt  time.Time
}

// #736 operator-configured OUTBOUND alert sinks. format shapes the POST body: generic=our alert JSON, discord={content}, slack={text}. NOT the inbound provider-webhook ingestion surface.
type OpenrailsMerchantWebhook struct {
	ID         uuid.UUID
	MerchantID uuid.UUID
	Name       string
	Url        string
	Format     string
	Enabled    bool
	CreatedAt  time.Time
	UpdatedAt  time.Time
}

// #672 per-period metered-rating watermark: cumulative accrued amount + rated-through cutoff per (payer, currency, meter source, period start), so overlapping invoice closes bill each unit of usage exactly once.
type OpenrailsMeteredRatingWatermark struct {
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	Currency   string
	// Meter accrual source key (metered:<meter>[:rate_card:<id>][:dim:<value>]).
	Source       string
	PeriodFrom   time.Time
	RatedThrough time.Time
	// Micros already accrued for [period_from, rated_through); the sweep accrues only the delta above this.
	AccruedAmount int64
	CreatedAt     time.Time
	UpdatedAt     time.Time
}

// Per-(merchant, customer, currency) spend policy and money-in config. Amount values use the row currency internal precision. Admission reads billing_mode + credit_limit_amount + the ledger balance; per-invoker caps live in payer/invoker_spend_limits; arrears owed exposure is derived from open invoices.
type OpenrailsMoneySetting struct {
	MerchantID  uuid.UUID
	CustomerID  uuid.UUID
	BillingMode string
	// Optional low-balance trigger in the row currency internal precision.
	LowBalanceThreshold      *int64
	AutoTopupEnabled         bool
	AutoTopupAmount          *int64
	AutoTopupPaymentMethodID *uuid.UUID
	// per-account default credit-grant expiry in HOURS; NULL = no default.
	DefaultCreditExpiryHours *int32
	LastTopupAt              *time.Time
	CreatedAt                time.Time
	UpdatedAt                time.Time
	Tier                     *string
	// auto = tier maintained by tier_schedule auto-graduation; admin = explicit override that auto-graduation must not overwrite.
	TierSource string
	// System currency code (USD/EUR/JPY); the Go registry is the authority. Stablecoins and crypto tokens are payment assets, not account currencies.
	Currency string
	// Admin-set arrears credit line in the row currency internal precision. 0 = no arrears capacity; prepaid balance may still be spent.
	CreditLimitAmount         int64
	CollectionPaymentMethodID *uuid.UUID
}

// Queue for user notifications related to billing and subscriptions
type OpenrailsNotificationQueue struct {
	ID         uuid.UUID
	EventType  string
	Data       []byte
	Seen       bool
	CreatedAt  time.Time
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	// #789: when the notification email was sent; NULL = undelivered (the notification_email_sweep retries).
	EmailedAt *time.Time
}

// #690 episode analytics, the mirror of freeloader_episodes: spans where payment coverage existed (subscription paid-through snapshot, or a completed one_off payment with a finite access window for an entitlement-promising product) but no entitlement window covered the time. Open episodes (paid-through still in the future) end at now(). Same approximations: paid-through is the current-period snapshot; window coverage is contiguous-from-the-left (uncovered TAIL only — a wrongly-early revocation shows as the tail from revoked_at to paid-through).
type OpenrailsOrphanedEpisode struct {
	MerchantID uuid.UUID
	CustomerID uuid.UUID
	SourceType string
	SourceID   uuid.UUID
	ProductID  uuid.UUID
	StartedAt  interface{}
	EndedAt    interface{}
	Open       bool
	Days       float64
}

// Records of all payment transactions (formerly purchases table)
type OpenrailsPayment struct {
	ID            uuid.UUID
	PriceID       uuid.UUID
	Rail          string
	TransactionID string
	Amount        int64
	ListAmount    int64
	Currency      string
	Status        OpenrailsPaymentStatus
	// Links a payment to the subscription that generated it (nullable for one-off payments)
	SubscriptionID           *uuid.UUID
	RefundedPaymentID        *uuid.UUID
	DiscountCode             *string
	DiscountReason           *string
	DiscountMetadata         []byte
	EntitlementsSpecSnapshot []byte
	CreditsSpecSnapshot      []byte
	Metadata                 []byte
	PurchasedAt              time.Time
	CreatedAt                time.Time
	CardBrand                *string
	CardLast4                *string
	MerchantID               uuid.UUID
	CustomerID               uuid.UUID
	// PSP that took this charge. Required on every real rail (payments_psp_required_on_rail); NULL only for off-rail channels (manual/admin), which have no provider — or#893.
	PspID *uuid.UUID
	// #733 initial|renewal, stamped at write time by the checkout vs rebill paths; NULL = unknown (imported/pre-instrumentation rows).
	AttemptKind *string
	// #733 raw rail decline code, recorded verbatim (no fabrication).
	FailureCode *string
	// #733 normalized decline category, derived deterministically from failure_code per rail.
	FailureReason *string
	// #733 discriminates mirror rows: refund | chargeback | dispute_reversal (dispute won). NULL on sale rows.
	ReversalKind *string
	// #796 credential form presented to the network: network_token | pan_via_proxy | psp_token. NULL = unknown/legacy; excluded from token_type-dimensioned metrics.
	TokenType *string
	// or#858 soft delete: set, the row is invisible to every live read. Only `pull-provider --prune` sets it, and `openrails undo-run` clears it.
	DeletedAt        *time.Time
	DestructiveRunID *uuid.UUID
	// or#827 rail|none — positive marker for real money movement at the payment rail. 'rail' rows carry a rail-issued transaction_id and are the ONLY rows the host settlement feed publishes; 'none' rows are bookkeeping (attempt anchors, declines, placeholders). Fail-closed default: undeclared = 'none'.
	MoneyMovement string
}

// Generalized payment method table supporting multiple rails.
type OpenrailsPaymentMethod struct {
	ID uuid.UUID
	// Payment rail type: nmi, ccbill, stripe, etc.
	Rail                 string
	InitialTransactionID string
	LastFour             *string
	CardType             *string
	ExpiryDate           *string
	Metadata             []byte
	CreatedAt            time.Time
	UpdatedAt            time.Time
	MerchantID           uuid.UUID
	CustomerID           uuid.UUID
	// PSP that vaulted this payment method. Required (or#893).
	PspID uuid.UUID
	// Customer-scope rail handle (e.g. NMI customer_vault_id); '' when the customer scope lives in rail_customers (Stripe).
	RailCustomerRef string
	// Instrument-scope rail handle (e.g. NMI billing_id, Stripe pm_, Spreedly/HyperSwitch token).
	RailMethodRef string
	RebillDriver  string
	// Rail-scoped stored-credential replay reference for the RECURRING card-network agreement (NMI: gateway transactionid of the initial recurring CIT, replayed as initial_transaction_id on recurring MITs). Empty = not captured yet.
	StoredCredentialRecurringRef string
	// Rail-scoped stored-credential replay reference for the UNSCHEDULED card-network agreement (NMI: gateway transactionid of the initial unscheduled CIT, replayed as initial_transaction_id on unscheduled MITs). Empty = not captured yet.
	StoredCredentialUnscheduledRef string
	// or#880 who HOLDS this instrument, orthogonal to who charges it (rail + psp_id): psp = stored at the processor itself (Stripe pm_, NMI customer vault) | basis_theory = neutral third-party vault (#795). Never empty — "no stored instrument" (CCBill, Solana) is the absence of a row, not a custodian value.
	Custodian string
	// Custodian-issued stable fingerprint of the underlying PAN (Basis Theory's default fingerprint expression), for dedup/lookup. '' = the custodian issues none.
	Fingerprint string
	// #795 BT network-token uuid; '' = not provisioned.
	NetworkTokenID string
	// #795 NT lifecycle status: ''|active|inactive|suspended|deleted (webhook-folded; never touches PAN-side expiry).
	NetworkTokenStatus string
	// #795 payment account reference from NT provisioning.
	NetworkTokenPar string
	// #795 per-instrument charge routing: pan_proxy (detokenized FPAN through the vault proxy) | network_token (DPAN; gated off on NMI gateways).
	ChargeVia string
	// #795 instrument park marker (cancellation-last-resort): non-empty = vault-side problem (token deleted/expired, closed account); charges fail loudly, operator notified, subscriptions NEVER terminally cancelled by this.
	ParkReason string
	// #795 when the instrument was parked; NULL = not parked.
	ParkedAt *time.Time
	// or#795: when this instrument was last SUBMITTED to a batch account-updater cycle (not when it last changed). NULL = never. The staleness half of the due-work predicate: an instrument refreshed inside the lookahead window is not re-submitted, so one renewal cycle costs at most one network lookup per card.
	AccountUpdaterCheckedAt *time.Time
}

// or#870 bucket 2: one open row per subscription parked awaiting a payment-method fix, driving the notification ladder. Sends notices only — no path from this table cancels a subscription or touches a stored payment method.
type OpenrailsPaymentMethodNotice struct {
	ID             uuid.UUID
	MerchantID     uuid.UUID
	CustomerID     uuid.UUID
	SubscriptionID uuid.UUID
	Rail           string
	FailureCode    *string
	ParkedAt       time.Time
	RungsSent      int64
	NextNoticeAt   *time.Time
	ResolvedAt     *time.Time
	Resolution     *string
	CreatedAt      time.Time
	UpdatedAt      time.Time
}

// Durable host-consumption queue for real successful payments; consumers ack after idempotent processing.
type OpenrailsPaymentSettlementEvent struct {
	ID          uuid.UUID
	MerchantID  uuid.UUID
	PaymentID   uuid.UUID
	Amount      int64
	Currency    string
	SettledAt   time.Time
	DeliveredAt *time.Time
}

// Pricing tiers for products with rail-specific identifiers
type OpenrailsPrice struct {
	ID        uuid.UUID
	ProductID uuid.UUID
	// Price amount in row currency micros (1 major unit = 1,000,000).
	Amount   int64
	Currency string
	// PSP link entries keyed by PSP key (e.g. mobius); each entry records its rail and the provider-side object ids (plan_id, price_id, ...).
	PspLinks   []byte
	Archived   bool
	CreatedAt  time.Time
	UpdatedAt  time.Time
	MerchantID uuid.UUID
	// access window in HOURS a purchase grants; NULL = indefinite/durable. For auto_renew, hours/24 is the provider billing cadence in days.
	AccessDurationHours *int32
	// #622 whether the price recharges and extends the window after access_duration_hours (recurring).
	AutoRenew bool
	// #622 optional first-phase price (micros); 0 = free trial; NULL = no trial.
	TrialUnitAmount *int64
	// optional trial first-phase length in HOURS; NULL = no trial.
	TrialDurationHours *int32
	// #774: durable per-merchant-unique handle for this price's substance-version chain. Immutable identity-wise (the row's id is still the #662 substance UUID) but the LABEL can be relabeled in place (a key rename). At most one non-archived row per (merchant_id, key) — see uq_prices_merchant_key_current. Archived rows keep their key as a back-reference to the chain.
	Key string
}

// #774: append-only log of when a price key's current pointer moved to which price row. History, not row identity — a row can appear more than once (reactivation).
type OpenrailsPriceKeyMovement struct {
	ID          uuid.UUID
	MerchantID  uuid.UUID
	Key         string
	PriceID     uuid.UUID
	EffectiveAt time.Time
	CreatedAt   time.Time
}

// Cached NMI test-mode probe verdicts (#348): one row per (rail, sha256(security_key)). Fresh 'live' refuses boot from cache, fresh 'simulated' skips the probe, stale/missing re-probes. RLS-exempt by design: instance-level credential state, not tenant data.
type OpenrailsProbeVerdict struct {
	Rail string
	// sha256 hex of the rail security key. A rotated key hashes differently, so the cache never answers for a credential it has not seen.
	KeyHash   string
	Verdict   string
	CheckedAt time.Time
}

// Product definitions that can be purchased or subscribed to
type OpenrailsProduct struct {
	ID               uuid.UUID
	Key              string
	DisplayName      string
	Description      *string
	EntitlementsSpec []byte
	// Bundled promo credits spec (amount, expiry, cadence) for subscriptions
	CreditsSpec []byte
	// Semantic group name for mutually-exclusive products (e.g., "premium"). Products in same group require upgrade/downgrade, not parallel ownership.
	TierGroup *string
	// Tier ranking within group. Higher = more premium. Used to determine upgrade (higher rank) vs downgrade (lower rank) direction.
	TierRank   int32
	Archived   bool
	CreatedAt  time.Time
	UpdatedAt  time.Time
	MerchantID uuid.UUID
}

// #611 catalog bundle includes: parent product grants/owns included catalog products when materialized.
